function fee(x) { x = Math.max(0, Number(x) || 0); return 0.2 * Math.min(x, 10000) + 0.1 * Math.max(x - 10000, 0); }
function money(n) { return '$' + Math.round(Number(n) || 0).toLocaleString('en-US'); }
function digits(v) { return String(v == null ? '' : v).replace(/[^0-9]/g, ''); }
function lower(s) { return String(s || '').charAt(0).toLowerCase() + String(s || '').slice(1); }
function dueDate(iso, days) {
  if (!iso) { return ''; }
  var d = new Date(iso + 'T12:00:00');
  if (isNaN(d.getTime())) { return ''; }
  d.setDate(d.getDate() + days);
  return d.toLocaleDateString('es-US', {weekday: 'short', month: 'short', day: 'numeric'});
}

