        what: (st.req.trade ? lower(st.req.trade) : 'su oficio') + (st.req.zip ? ' cerca de ' + st.req.zip : ''),
        setTrade: function (e) { self.patch('req', {trade: e && e.target ? e.target.value : ''}); },
